def q(s): return "'" + s.replace("'", "''") + "'"

if __name__ == '__main__':
    seen = set()
    for it in ITEMS:
        assert it[3] not in seen, it[3]; seen.add(it[3])
        assert it[0] in ('Starter','Beginner','Intermediate','Advanced') and it[2] in (C, L)
    rows = []
    order = {}
    for lv, unit, tier, pat, desc in ITEMS:
        order[lv] = order.get(lv, 0) + 1
        rows.append(f"  ({q(pat)}, {q(lv)}, {order[lv]}, {q(desc)}, {q(unit)}, {q(tier)})")
    print("-- auto-apply")
    print("-- Generated by supabase/seeds/grammar_curriculum.py — edit the .py, then regenerate.")
    print("-- Grammar curriculum v2: Seed/Sprout/Tree/Forest × units, core (Grammar Path)")
    print("-- vs library. Shells only — lessons are generated on first open and cached")
    print("-- in grammar_examples_cache (gf-curr2::<pattern>). Legacy pattern strings are")
    print("-- kept so progress carries over; patterns not in this list are deactivated")
    print("-- (not deleted). Idempotent.")
    print()
    print("alter table public.grammar_curriculum")
    print("  add column if not exists unit text,")
    print("  add column if not exists tier text not null default 'core';")
    print("-- Drop exact-duplicate pattern rows (keep the first) so the unique index can build.")
    print("delete from public.grammar_curriculum a using public.grammar_curriculum b where a.pattern = b.pattern and a.ctid > b.ctid;")
    print("create unique index if not exists grammar_curriculum_pattern_uq on public.grammar_curriculum (pattern);")
    print()
    print("insert into public.grammar_curriculum (pattern, level, sort_order, description, unit, tier, active)")
    print("select v.pattern, v.level, v.sort_order, v.description, v.unit, v.tier, true from (values")
    print(",\n".join(rows))
    print(") as v(pattern, level, sort_order, description, unit, tier)")
    print("on conflict (pattern) do update set")
    print("  level = excluded.level, sort_order = excluded.sort_order, description = excluded.description,")
    print("  unit = excluded.unit, tier = excluded.tier, active = true;")
    print()
    pats = ", ".join(q(it[3]) for it in ITEMS)
    print(f"update public.grammar_curriculum set active = false where pattern not in ({pats});")
